``` 
        K_WORK_RUNNING_BIT = 0,
	K_WORK_CANCELING_BIT = 1,  /*MAY be set simultaneously with other bits*/
	K_WORK_QUEUED_BIT = 2,     
	K_WORK_DELAYED_BIT = 3,`  /*On the timer queue. Only valid if DELAYABLE*/
